56	public class ManualEntryDialog {
57	    public static void show(final MainActivity callingActivity, Settings settings, final EntriesCardAdapter adapter) {
58	        AppCompatDelegate.setCompatVectorFromResourcesEnabled(true);
59	
60	        ViewGroup container = callingActivity.findViewById(R.id.main_content);
61	        View inputView = callingActivity.getLayoutInflater().inflate(R.layout.dialog_manual_entry, container, false);
62	
63	        if (settings.getBlockAccessibility())
64	            inputView.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS);
65	
66	        final Spinner typeInput = inputView.findViewById(R.id.manual_type);
67	        final EditText issuerInput = inputView.findViewById(R.id.manual_issuer);
68	        final EditText labelInput = inputView.findViewById(R.id.manual_label);
69	        final EditText secretInput = inputView.findViewById(R.id.manual_secret);
70	        final EditText counterInput = inputView.findViewById(R.id.manual_counter);
71	        final EditText periodInput = inputView.findViewById(R.id.manual_period);
72	        final EditText digitsInput = inputView.findViewById(R.id.manual_digits);
73	        final LinearLayout counterLayout = inputView.findViewById(R.id.manual_layout_counter);
74	        final LinearLayout periodLayout = inputView.findViewById(R.id.manual_layout_period);
75	        final Spinner algorithmInput = inputView.findViewById(R.id.manual_algorithm);
76	        final Button tagsInput = inputView.findViewById(R.id.manual_tags);
77	
78	        final ArrayAdapter<TokenCalculator.HashAlgorithm> algorithmAdapter = new ArrayAdapter<>(callingActivity, android.R.layout.simple_expandable_list_item_1, TokenCalculator.HashAlgorithm.values());
79	        final ArrayAdapter<Entry.OTPType> typeAdapter = new ArrayAdapter<>(callingActivity, android.R.layout.simple_expandable_list_item_1, Entry.PublicTypes.toArray(new Entry.OTPType[Entry.PublicTypes.size()]));
80	        final ArrayAdapter<Entry.OTPType> fullTypeAdapter = new ArrayAdapter<>(callingActivity, android.R.layout.simple_expandable_list_item_1, Entry.OTPType.values());
81	
82	        if (settings.getSpecialFeatures())
83	            typeInput.setAdapter(fullTypeAdapter);
84	        else
85	            typeInput.setAdapter(typeAdapter);
86	
87	        algorithmInput.setAdapter(algorithmAdapter);
88	
89	        periodInput.setText(String.format(Locale.US, "%d", TokenCalculator.TOTP_DEFAULT_PERIOD));
90	        digitsInput.setText(String.format(Locale.US, "%d", TokenCalculator.TOTP_DEFAULT_DIGITS));
91	        counterInput.setText(String.format(Locale.US, "%d", TokenCalculator.HOTP_INITIAL_COUNTER));
92	
93	        typeInput.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener() {
94	            @Override
95	            public void onItemSelected(AdapterView<?> adapterView, View view, int i, long l) {
96	                Entry.OTPType type = (Entry.OTPType) adapterView.getSelectedItem();
97	
98	                if (type == Entry.OTPType.STEAM) {
99	                    counterLayout.setVisibility(View.GONE);
100	                    periodLayout.setVisibility(View.VISIBLE);
101	
102	                    digitsInput.setText(String.format(Locale.US, "%d", TokenCalculator.STEAM_DEFAULT_DIGITS));
103	                    periodInput.setText(String.format(Locale.US, "%d", TokenCalculator.TOTP_DEFAULT_PERIOD));
104	                    algorithmInput.setSelection(algorithmAdapter.getPosition(TokenCalculator.HashAlgorithm.SHA1));
105	
106	                    digitsInput.setEnabled(false);
107	                    periodInput.setEnabled(false);
108	                    algorithmInput.setEnabled(false);
109	                } else if (type == Entry.OTPType.TOTP) {
110	                    counterLayout.setVisibility(View.GONE);
111	                    periodLayout.setVisibility(View.VISIBLE);
112	
113	                    digitsInput.setText(String.format(Locale.US, "%d", TokenCalculator.TOTP_DEFAULT_DIGITS));
114	                    digitsInput.setEnabled(true);
115	                    periodInput.setEnabled(true);
116	                    algorithmInput.setEnabled(true);
117	                } else if (type == Entry.OTPType.HOTP) {
118	                    counterLayout.setVisibility(View.VISIBLE);
119	                    periodLayout.setVisibility(View.GONE);
120	
121	                    digitsInput.setText(String.format(Locale.US, "%d", TokenCalculator.TOTP_DEFAULT_DIGITS));
122	                    digitsInput.setEnabled(true);
123	                    periodInput.setEnabled(true);
124	                    algorithmInput.setEnabled(true);
125	                }
126	            }
127	
128	            @Override
129	            public void onNothingSelected(AdapterView<?> adapterView) {
130	
131	            }
132	        });
133	
134	        List<String> allTags = adapter.getTags();
135	        HashMap<String, Boolean> tagsHashMap = new HashMap<>();
136	        for(String tag: allTags) {
137	            tagsHashMap.put(tag, false);
138	        }
139	        final TagsAdapter tagsAdapter = new TagsAdapter(callingActivity, tagsHashMap);
140	
141	        final Callable tagsCallable = new Callable() {
142	            @Override
143	            public Object call() throws Exception {
144	                List<String> selectedTags = tagsAdapter.getActiveTags();
145	                StringBuilder stringBuilder = new StringBuilder();
146	                for(int j = 0; j < selectedTags.size(); j++) {
147	                    stringBuilder.append(selectedTags.get(j));
148	                    if(j < selectedTags.size() - 1) {
149	                        stringBuilder.append(", ");
150	                    }
151	                }
152	                tagsInput.setText(stringBuilder.toString());
153	                return null;
154	            }
155	        };
156	
157	        tagsInput.setOnClickListener(new View.OnClickListener() {
158	            @Override
159	            public void onClick(View view) {
160	                TagsDialog.show(callingActivity, tagsAdapter, tagsCallable, tagsCallable);
161	            }
162	        });
163	
164	        final Button expandButton = inputView.findViewById(R.id.dialog_expand_button);
165	
166	        // Dirty fix for the compound drawable to avoid crashes on KitKat
167	        expandButton.setCompoundDrawablesWithIntrinsicBounds(null, null, callingActivity.getResources().getDrawable(R.drawable.ic_arrow_down_accent), null);
168	
169	        final ExpandableLinearLayout expandLayout = inputView.findViewById(R.id.dialog_expand_layout);
170	
171	        expandButton.setOnClickListener(new View.OnClickListener() {
172	            @Override
173	            public void onClick(View view) {
174	                expandLayout.toggle();
175	            }
176	        });
177	
178	        expandLayout.setListener(new ExpandableLayoutListenerAdapter() {
179	            @Override
180	            public void onOpened() {
181	                super.onOpened();
182	                expandButton.setCompoundDrawablesRelativeWithIntrinsicBounds(0, 0, R.drawable.ic_arrow_up_accent, 0);
183	            }
184	
185	            @Override
186	            public void onClosed() {
187	                super.onClosed();
188	                expandButton.setCompoundDrawablesRelativeWithIntrinsicBounds(0, 0, R.drawable.ic_arrow_down_accent, 0);
189	            }
190	        });
191	
192	        AlertDialog.Builder builder = new AlertDialog.Builder(callingActivity);
193	        builder.setTitle(R.string.dialog_title_manual_entry)
194	                .setView(inputView)
195	                .setPositiveButton(R.string.button_save, new DialogInterface.OnClickListener() {
196	                    @Override
197	                    public void onClick(DialogInterface dialogInterface, int i) {
198	                        Entry.OTPType type = (Entry.OTPType) typeInput.getSelectedItem();
199	                        TokenCalculator.HashAlgorithm algorithm = (TokenCalculator.HashAlgorithm) algorithmInput.getSelectedItem();
200	
201	                        String issuer = issuerInput.getText().toString();
202	                        String label = labelInput.getText().toString();
203	                        //Replace spaces with empty characters
204	                        String secret = secretInput.getText().toString().replaceAll("\\s+","");
205	                        int digits = Integer.parseInt(digitsInput.getText().toString());
206	
207	                        if (type == Entry.OTPType.TOTP || type == Entry.OTPType.STEAM) {
208	                            int period = Integer.parseInt(periodInput.getText().toString());
209	
210	                            Entry e = new Entry(type, secret, period, digits, issuer, label, algorithm, tagsAdapter.getActiveTags());
211	                            e.updateOTP();
212	                            e.setLastUsed(System.currentTimeMillis());
213	                            adapter.addEntry(e);
214	
215	                            callingActivity.refreshTags();
216	                        } else if (type == Entry.OTPType.HOTP) {
217	                            long counter = Long.parseLong(counterInput.getText().toString());
218	
219	                            Entry e = new Entry(type, secret, counter, digits, issuer, label, algorithm, tagsAdapter.getActiveTags());
220	                            e.updateOTP();
221	                            e.setLastUsed(System.currentTimeMillis());
222	                            adapter.addEntry(e);
223	                        }
224	                    }
225	                })
226	                .setNegativeButton(android.R.string.cancel, new DialogInterface.OnClickListener() {
227	                    @Override
228	                    public void onClick(DialogInterface dialogInterface, int i) {}
229	                });
230	
231	        AlertDialog dialog = builder.create();
232	        dialog.show();
233	
234	        final Button positiveButton = dialog.getButton(AlertDialog.BUTTON_POSITIVE);
235	        positiveButton.setEnabled(false);
236	
237	        TextWatcher watcher = new TextWatcher() {
238	            @Override
239	            public void beforeTextChanged(CharSequence charSequence, int i, int i1, int i2) {
240	            }
241	
242	            @Override
243	            public void onTextChanged(CharSequence charSequence, int i, int i1, int i2) {
244	            }
245	
246	            @Override
247	            public void afterTextChanged(Editable editable) {
248	                if (TextUtils.isEmpty(labelInput.getText()) || TextUtils.isEmpty(secretInput.getText())
249	                        || TextUtils.isEmpty(digitsInput.getText()) || Integer.parseInt(digitsInput.getText().toString()) == 0) {
250	                    positiveButton.setEnabled(false);
251	                } else {
252	                    Entry.OTPType type = (Entry.OTPType) typeInput.getSelectedItem();
253	                    if (type == Entry.OTPType.HOTP) {
254	                        if (TextUtils.isEmpty(counterInput.getText())) {
255	                            positiveButton.setEnabled(false);
256	                        } else {
257	                            positiveButton.setEnabled(true);
258	                        }
259	                    } else if (type == Entry.OTPType.TOTP || type == Entry.OTPType.STEAM) {
260	                        if (TextUtils.isEmpty(periodInput.getText()) || Integer.parseInt(periodInput.getText().toString()) == 0) {
261	                            positiveButton.setEnabled(false);
262	                        } else {
263	                            positiveButton.setEnabled(true);
264	                        }
265	                    } else {
266	                        positiveButton.setEnabled(true);
267	                    }
268	                }
269	            }
270	        };
271	
272	        labelInput.addTextChangedListener(watcher);
273	        secretInput.addTextChangedListener(watcher);
274	        periodInput.addTextChangedListener(watcher);
275	        digitsInput.addTextChangedListener(watcher);
276	        counterInput.addTextChangedListener(watcher);
277	    }
278	}
