109	    public static String formatToken(String s, int chunkSize) {
110	        if (chunkSize ==0 || s == null)
111	            return s;
112	
113	        StringBuilder ret = new StringBuilder("");
114	        int index = s.length();
115	        while (index > 0) {
116	            ret.insert(0, s.substring(Math.max(index - chunkSize, 0), index));
117	            ret.insert(0, " ");
118	            index = index - chunkSize;
119	        }
120	        return ret.toString().trim();
121	    }
