import org.apache.commons.codec.binary.Base32;

import java.io.File;

/* Check if a string is a valid, decodable base32 secret */
public static boolean isValidBase32(String secret) {
    if (secret == null)
        return false;

    // Ignore whitespace, it is stripped before the secret is used anyway
    String cleanSecret = secret.replaceAll("\\s+", "").toUpperCase(Locale.ENGLISH);

    if (cleanSecret.isEmpty())
        return false;

    Base32 base32 = new Base32();

    // Reject anything that is not part of the base32 alphabet,
    // those characters would silently be dropped while decoding
    if (!base32.isInAlphabet(cleanSecret, true))
        return false;

    try {
        // Decoding is strict, it fails if e.g. the length of the secret is invalid
        byte[] decoded = base32.decode(cleanSecret);

        // A secret that decodes to nothing is useless
        return decoded.length > 0;
    } catch (Exception e) {
        return false;
    }
}

